import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const v1 = JSON.parse(await readFile(path.join(root, "protocol/acp/v1/schema.json"), "utf8"));
const v2 = JSON.parse(await readFile(path.join(root, "protocol/acp/v2-preview/schema.json"), "utf8"));
const v1Definitions = Object.keys(v1.$defs ?? v1.definitions ?? {}).sort();
const v2Definitions = Object.keys(v2.$defs ?? v2.definitions ?? {}).sort();
const outputDirectory = path.join(root, "protocol/acp/generated");
await mkdir(outputDirectory, { recursive: true });
const result = {
  schemaVersion: "1.0",
  comparison: "acp-v1-to-v2-preview",
  v1DefinitionCount: v1Definitions.length,
  v2PreviewDefinitionCount: v2Definitions.length,
  addedDefinitions: v2Definitions.filter((name) => !v1Definitions.includes(name)),
  removedDefinitions: v1Definitions.filter((name) => !v2Definitions.includes(name)),
};
await writeFile(path.join(outputDirectory, "v1-to-v2-preview.diff.json"), `${JSON.stringify(result, null, 2)}\n`);

