import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { buildAcpDiff, readAcpInputs } from "./lib/acp-contract.mjs";

const root = process.cwd();
const [v1, v2] = await readAcpInputs(root);
const outputDirectory = path.join(root, "protocol/acp/generated");
await mkdir(outputDirectory, { recursive: true });
await writeFile(
  path.join(outputDirectory, "v1-to-v2-preview.diff.json"),
  `${JSON.stringify(buildAcpDiff(v1.document, v2.document), null, 2)}\n`,
);
